routerAdd('GET','/api/pfriends/broadcasts',(e)=>{const u=require(`${__hooks}/broadcast-utils.js`);u.auth(e,'AWARDEE');const a=e.app.findFirstRecordByData('awardees','user',e.auth.id);return e.json(200,{broadcasts:e.app.findRecordsByFilter('broadcasts','status="TERKIRIM" && (audience="SEMUA" || audience={:a})','-sentAt',0,0,{a:a.getString('community')}).map(x=>u.dto(e.app,x,e.auth.id))})},$apis.requireAuth('users'));
routerAdd('POST','/api/pfriends/broadcasts/{id}/start',(e)=>{require(`${__hooks}/broadcast-utils.js`).auth(e,'AWARDEE');const b=e.app.findRecordById('broadcasts',e.request.pathValue('id'));let r;try{r=e.app.findFirstRecordByFilter('broadcast_engagements','broadcast={:b} && owner={:o} && type="BROADCAST_VIEW"',{b:b.id,o:e.auth.id})}catch(_){r=new Record(e.app.findCollectionByNameOrId('broadcast_engagements'));r.set('broadcast',b.id);r.set('owner',e.auth.id);r.set('awardeeId',e.auth.getString('awardeeId'));r.set('type','BROADCAST_VIEW');r.set('startedAt',new Date().toISOString());e.app.save(r)}return e.json(200,{unlockAt:new Date(new Date(r.getString('startedAt')).getTime()+15000).toISOString()})},$apis.requireAuth('users'));
routerAdd('POST','/api/pfriends/broadcasts/{id}/engage',(e)=>{const u=require(`${__hooks}/broadcast-utils.js`);u.auth(e,'AWARDEE');const b=new DynamicModel({type:'',response:'',requestKey:''});e.bindBody(b);if(!u.SCORE[b.type])throw new BadRequestError('Jenis engagement tidak dikenal.');let out;try{out=u.award(e.app,e,e.app.findRecordById('broadcasts',e.request.pathValue('id')),b.type,b.response,b.requestKey)}catch(error){throw new BadRequestError(`Engagement gagal: ${String(error)}`)}require(`${__hooks}/gamification-utils.js`).ensureProfile(e.app,e.app.findFirstRecordByData('awardees','user',e.auth.id));return e.json(200,{points:out.getInt('points')})},$apis.requireAuth('users'));
routerAdd('GET','/api/pfriends/admin/broadcasts',(e)=>{const u=require(`${__hooks}/broadcast-utils.js`);u.auth(e,'ADMIN');return e.json(200,{broadcasts:e.app.findRecordsByFilter('broadcasts','id!=""','-sentAt',0,0).map(x=>u.dto(e.app,x,''))})},$apis.requireAuth('users'));
routerAdd('GET','/api/pfriends/verifier/broadcasts',(e)=>{if(!e.auth||e.auth.getString('role')!=='VERIFIER'||e.auth.getString('status')!=='AKTIF')throw new ForbiddenError('Sesi Verifikator aktif diperlukan.');const u=require(`${__hooks}/broadcast-utils.js`);return e.json(200,{broadcasts:e.app.findRecordsByFilter('broadcasts','id!=""','-sentAt',0,0).map(x=>u.dto(e.app,x,''))})},$apis.requireAuth('users'));
routerAdd('POST','/api/pfriends/admin/broadcasts',(e)=>{const u=require(`${__hooks}/broadcast-utils.js`);u.auth(e,'ADMIN');const b=new DynamicModel({title:'',summary:'',body:'',channel:'SEMUA',contentSource:'',lightCta:'',ctaLink:'',audience:'SEMUA',scheduledAt:''});e.bindBody(b);const r=new Record(e.app.findCollectionByNameOrId('broadcasts'));u.fill(r,b);r.set('createdBy',e.auth.id);e.app.save(r);return e.json(201,u.dto(e.app,r,''))},$apis.requireAuth('users'));
routerAdd('PATCH','/api/pfriends/admin/broadcasts/{id}',(e)=>{const u=require(`${__hooks}/broadcast-utils.js`);u.auth(e,'ADMIN');const r=e.app.findRecordById('broadcasts',e.request.pathValue('id'));if(r.getString('status')==='TERKIRIM')throw new BadRequestError('Kabar terkirim tidak dapat disunting.');const b=new DynamicModel({title:'',summary:'',body:'',channel:'',contentSource:'',lightCta:'',ctaLink:'',audience:'',scheduledAt:''});e.bindBody(b);u.fill(r,b);r.set('updatedBy',e.auth.id);e.app.save(r);return e.json(200,u.dto(e.app,r,''))},$apis.requireAuth('users'));
routerAdd('POST','/api/pfriends/admin/broadcasts/{id}/publish',(e)=>{const u=require(`${__hooks}/broadcast-utils.js`);u.auth(e,'ADMIN');const r=e.app.findRecordById('broadcasts',e.request.pathValue('id'));if(r.getString('status')!=='TERKIRIM'){r.set('status','TERKIRIM');r.set('sentAt',new Date().toISOString());const a=r.getString('audience');r.set('recipientCount',e.app.findRecordsByFilter('awardees',a==='SEMUA'?'status="AKTIF"':'status="AKTIF" && community={:a}','',0,0,{a}).length);r.set('updatedBy',e.auth.id);e.app.save(r)}return e.json(200,u.dto(e.app,r,''))},$apis.requireAuth('users'));
routerAdd('DELETE','/api/pfriends/admin/broadcasts/{id}',(e)=>{require(`${__hooks}/broadcast-utils.js`).auth(e,'ADMIN');const r=e.app.findRecordById('broadcasts',e.request.pathValue('id'));if(r.getString('status')==='TERKIRIM')throw new BadRequestError('Kabar terkirim tidak dapat dihapus.');e.app.delete(r);return e.noContent(204)},$apis.requireAuth('users'));
cronAdd('pfriends-publish-broadcasts','*/1 * * * *',()=>{const now=new Date();for(const r of $app.findRecordsByFilter('broadcasts','status="TERJADWAL" && scheduledAt<={:now}','',0,0,{now:now.toISOString()})){r.set('status','TERKIRIM');r.set('sentAt',now.toISOString());const a=r.getString('audience');r.set('recipientCount',$app.findRecordsByFilter('awardees',a==='SEMUA'?'status="AKTIF"':'status="AKTIF" && community={:a}','',0,0,{a}).length);$app.save(r)}});
